  1→/**
  2→ * @fileoverview Slack bridge implementation using @slack/bolt.
  3→ *
  4→ * Connects Fetch to Slack workspaces via the Bolt SDK, supporting:
  5→ * - App mentions and direct messages
  6→ * - Thread-based conversations
  7→ * - File uploads
  8→ * - Channel-based context
  9→ *
 10→ * @module bridge/slack
 11→ */
 12→
 13→import type { MessageBridge, ChannelType } from '../interface.js';
 14→import { logger } from '../../utils/logger.js';
 15→import { SecurityGate, RateLimiter, validateInput } from '../../security/index.js';
 16→import { handleMessage, registerChannelSender } from '../../handler/index.js';
 17→import { pipeline } from '../../config/pipeline.js';
 18→import { formatTextForChannel } from '../../agent/channel-format.js';
 19→
 20→// =============================================================================
 21→// TYPES
 22→// =============================================================================
 23→
 24→/** Minimal Slack event shapes to avoid hard dependency on @slack/bolt types. */
 25→interface SlackMessageEvent {
 26→  type: string;
 27→  text: string;
 28→  user: string;
 29→  channel: string;
 30→  ts: string;
 31→  thread_ts?: string;
 32→  bot_id?: string;
 33→  files?: Array<{ url_private: string; mimetype: string; name: string }>;
 34→}
 35→
 36→interface SlackApp {
 37→  start: () => Promise<void>;
 38→  stop: () => Promise<void>;
 39→  event: (eventName: string, handler: (args: { event: SlackMessageEvent; say: SayFn }) => Promise<void>) => void;
 40→  client: {
 41→    chat: {
 42→      postMessage: (args: { channel: string; text: string; thread_ts?: string }) => Promise<{ ts?: string }>;
 43→    };
 44→    files: {
 45→      uploadV2: (args: { channel_id: string; content: string; filename: string; thread_ts?: string }) => Promise<void>;
 46→    };
 47→  };
 48→}
 49→
 50→type SayFn = (args: { text: string; thread_ts?: string } | string) => Promise<{ ts?: string }>;
 51→
 52→// =============================================================================
 53→// SLACK BRIDGE
 54→// =============================================================================
 55→
 56→export class SlackBridge implements MessageBridge {
 57→  readonly channel: ChannelType = 'slack';
 58→  private app: SlackApp | null = null;
 59→  private ready = false;
 60→  private securityGate: SecurityGate | null = null;
 61→  private rateLimiter: RateLimiter;
 62→  private botUserId: string | null = null;
 63→
 64→  private readonly botToken: string;
 65→  private readonly appToken: string;
 66→  private readonly signingSecret: string;
 67→
 68→  constructor(config: { botToken: string; appToken: string; signingSecret?: string }) {
 69→    this.botToken = config.botToken;
 70→    this.appToken = config.appToken;
 71→    this.signingSecret = config.signingSecret ?? '';
 72→    this.rateLimiter = new RateLimiter(pipeline.rateLimitMax, pipeline.rateLimitWindow);
 73→  }
 74→
 75→  async initialize(): Promise<void> {
 76→    logger.section('🔌 Initializing Slack Bridge');
 77→
 78→    try {
 79→      // Dynamic import to avoid hard dependency when Slack is not configured
 80→      const { App } = await import('@slack/bolt');
 81→
 82→      this.app = new App({
 83→        token: this.botToken,
 84→        appToken: this.appToken,
 85→        socketMode: true,
 86→        ...(this.signingSecret ? { signingSecret: this.signingSecret } : {}),
 87→      }) as unknown as SlackApp;
 88→
 89→      this.securityGate = await SecurityGate.create();
 90→
 91→      // Register message sender for proactive messages
 92→      registerChannelSender('slack', async (userId: string, text: string) => {
 93→        await this.sendMessage(userId, text);
 94→      });
 95→
 96→      this.setupEventHandlers();
 97→      await this.app.start();
 98→      this.ready = true;
 99→
100→      logger.success('Slack Bridge connected and listening');
101→    } catch (error) {
102→      const msg = error instanceof Error ? error.message : String(error);
103→      logger.error(`Failed to initialize Slack Bridge: ${msg}`);
104→      throw error;
105→    }
106→  }
107→
108→  async destroy(): Promise<void> {
109→    this.ready = false;
110→    this.rateLimiter.shutdown();
111→    if (this.securityGate) {
112→      await this.securityGate.shutdown();
113→    }
114→    if (this.app) {
115→      await this.app.stop();
116→      this.app = null;
117→    }
118→    logger.info('Slack Bridge destroyed');
119→  }
120→
121→  async sendMessage(target: string, text: string, options?: Record<string, unknown>): Promise<string | null> {
122→    if (!this.app) return null;
123→    try {
124→      const formatted = formatTextForChannel(text, 'slack');
125→      const result = await this.app.client.chat.postMessage({
126→        channel: target,
127→        text: formatted,
128→        thread_ts: options?.threadTs as string | undefined,
129→      });
130→      return result.ts ?? null;
131→    } catch (error) {
132→      logger.error('Failed to send Slack message', error);
133→      return null;
134→    }
135→  }
136→
137→  isReady(): boolean {
138→    return this.ready;
139→  }
140→
141→  // ===========================================================================
142→  // EVENT HANDLERS
143→  // ===========================================================================
144→
145→  private setupEventHandlers(): void {
146→    if (!this.app) return;
147→
148→    // Listen for app_mention events (when someone @mentions the bot)
149→    this.app.event('app_mention', async ({ event, say }: { event: SlackMessageEvent; say: SayFn }) => {
150→      await this.handleSlackMessage(event, say);
151→    });
152→
153→    // Listen for direct messages
154→    this.app.event('message', async ({ event, say }: { event: SlackMessageEvent; say: SayFn }) => {
155→      // Skip bot messages to prevent loops
156→      if (event.bot_id) return;
157→      // Only handle DMs (channel type starts with D)
158→      if (!event.channel.startsWith('D')) return;
159→      await this.handleSlackMessage(event, say);
160→    });
161→  }
162→
163→  private async handleSlackMessage(event: SlackMessageEvent, say: SayFn): Promise<void> {
164→    const senderId = event.user;
165→    if (!senderId) return;
166→
167→    // Skip messages from the bot itself
168→    if (this.botUserId && senderId === this.botUserId) return;
169→
170→    // Strip bot mention from message text
171→    let messageText = (event.text || '').replace(/<@[A-Z0-9]+>/g, '').trim();
172→    if (!messageText) return;
173→
174→    // Rate limiting
175→    if (!(await this.rateLimiter.isAllowed(senderId))) {
176→      await say({ text: 'Slow down! You\'re sending too many requests. Please wait a moment.', thread_ts: event.thread_ts || event.ts });
177→      return;
178→    }
179→
180→    // Input validation
181→    const validation = validateInput(messageText);
182→    if (!validation.valid) {
183→      await say({ text: `Error: ${validation.error}`, thread_ts: event.thread_ts || event.ts });
184→      return;
185→    }
186→
187→    const threadTs = event.thread_ts || event.ts;
188→
189→    try {
190→      const responses = await handleMessage(
191→        `slack:${senderId}`,
192→        validation.sanitized,
193→        async (text) => {
194→          const formatted = formatTextForChannel(text, 'slack');
195→          await say({ text: formatted, thread_ts: threadTs });
196→        },
197→      );
198→
199→      for (const response of responses) {
200→        const formatted = formatTextForChannel(response, 'slack');
201→        await say({ text: formatted, thread_ts: threadTs });
202→      }
203→    } catch (error) {
204→      logger.error('Failed to process Slack message', error);
205→      await say({ text: 'Sorry, I encountered an error processing your request.', thread_ts: threadTs });
206→    }
207→  }
208→}
209→

