  2→ * @fileoverview Discord bridge implementation using discord.js.
  3→ *
  4→ * Connects Fetch to Discord servers, supporting:
  5→ * - Channel-based messaging with mention triggers
  6→ * - Thread/reply context
  7→ * - Role-based access control
  8→ * - File attachments
  9→ *
 10→ * @module bridge/discord
 11→ */
 12→
 13→import type { MessageBridge, ChannelType } from '../interface.js';
 14→import { logger } from '../../utils/logger.js';
 15→import { RateLimiter, validateInput } from '../../security/index.js';
 16→import { handleMessage, registerChannelSender } from '../../handler/index.js';
 17→import { pipeline } from '../../config/pipeline.js';
 18→import { formatTextForChannel } from '../../agent/channel-format.js';
 19→
 20→// =============================================================================
 21→// TYPES
 22→// =============================================================================
 23→
 24→/** Minimal discord.js shapes to avoid hard dependency on discord.js types. */
 25→interface DiscordMessage {
 26→  id: string;
 27→  content: string;
 28→  author: { id: string; bot: boolean; username: string };
 29→  channel: {
 30→    id: string;
 31→    type: number;
 32→    send: (content: string) => Promise<{ id: string }>;
 33→    isDMBased: () => boolean;
 34→  };
 35→  guild?: { id: string };
 36→  member?: { roles: { cache: Map<string, { name: string }> } };
 37→  mentions: { has: (user: unknown) => boolean };
 38→  reference?: { messageId: string };
 39→  reply: (content: string) => Promise<{ id: string }>;
 40→}
 41→
 42→interface DiscordClient {
 43→  login: (token: string) => Promise<string>;
 44→  destroy: () => Promise<void>;
 45→  on: (event: string, handler: (...args: unknown[]) => void) => void;
 46→  once: (event: string, handler: (...args: unknown[]) => void) => void;
 47→  user?: { id: string; username: string; tag: string };
 48→  channels: {
 49→    fetch: (id: string) => Promise<{ send: (content: string) => Promise<{ id: string }> } | null>;
 50→  };
 51→}
 52→
 53→// =============================================================================
 54→// DISCORD BRIDGE
 55→// =============================================================================
 56→
 57→export class DiscordBridge implements MessageBridge {
 58→  readonly channel: ChannelType = 'discord';
 59→  private client: DiscordClient | null = null;
 60→  private ready = false;
 61→  private rateLimiter: RateLimiter;
 62→  private botUserId: string | null = null;
 63→
 64→  private readonly token: string;
 65→  private readonly allowedRoles: Set<string>;
 66→  private readonly allowedChannels: Set<string>;
 67→
 68→  constructor(config: { token: string; allowedRoles?: string[]; allowedChannels?: string[] }) {
