  1→/**
  2→ * @fileoverview Channel-specific message formatters.
  3→ *
  4→ * Each channel has different formatting constraints:
  5→ * - WhatsApp: *bold*, _italic_, monospace with backticks, 40-char line width
  6→ * - Slack: *bold*, _italic_, ```code blocks```, mrkdwn format
  7→ * - Telegram: *bold*, _italic_, `code`, MarkdownV2
  8→ * - Discord: **bold**, *italic*, ```code blocks```, full Markdown
  9→ *
 10→ * @module agent/channel-format
 11→ */
 12→
 13→import type { ResponseEnvelope } from './envelope.js';
 14→import type { ChannelType } from '../bridge/interface.js';
 15→import { composeWhatsAppResponse } from './composer.js';
 16→import { formatAndChunkForWhatsApp, formatForWhatsApp } from './whatsapp-format.js';
 17→import type { ResponseIntent } from './response-policy.js';
 18→
 19→// =============================================================================
 20→// PUBLIC API
 21→// =============================================================================
 22→
 23→/**
 24→ * Format a response envelope for a specific channel and split into send-ready chunks.
 25→ */
 26→export function formatForChannel(
 27→  envelope: ResponseEnvelope,
 28→  channel: ChannelType,
 29→  intent?: ResponseIntent,
 30→): string[] {
 31→  switch (channel) {
 32→    case 'whatsapp':
 33→      return formatAndChunkForWhatsApp(composeWhatsAppResponse(envelope), intent);
 34→    case 'slack':
 35→      return [composeSlackResponse(envelope)];
 36→    case 'telegram':
 37→      return [composeTelegramResponse(envelope)];
 38→    case 'discord':
 39→      return [composeDiscordResponse(envelope)];
 40→  }
 41→}
 42→
 43→/**
 44→ * Format raw text for a specific channel.
 45→ */
 46→export function formatTextForChannel(text: string, channel: ChannelType): string {
 47→  switch (channel) {
 48→    case 'whatsapp':
 49→      return formatForWhatsApp(text);
 50→    case 'slack':
 51→      return formatForSlack(text);
 52→    case 'telegram':
 53→      return formatForTelegram(text);
 54→    case 'discord':
 55→      return formatForDiscord(text);
 56→  }
 57→}
 58→
 59→// =============================================================================
 60→// SLACK FORMATTING
 61→// =============================================================================
 62→
 63→function severityEmoji(severity: ResponseEnvelope['severity']): string {
 64→  switch (severity) {
 65→    case 'success': return ':white_check_mark:';
 66→    case 'warning': return ':warning:';
 67→    case 'error': return ':x:';
 68→    default: return ':memo:';
 69→  }
 70→}
 71→
 72→function composeSlackResponse(envelope: ResponseEnvelope): string {
 73→  const lines: string[] = [];
 74→  const icon = envelope.emojiLevel === 'normal' ? severityEmoji(envelope.severity) : '';
 75→
 76→  if (envelope.title?.trim()) {
 77→    lines.push(`${icon} *${envelope.title.trim()}*`.trim());
 78→  }
 79→
 80→  lines.push(`${icon} ${envelope.summary}`.trim());
 81→
 82→  for (const fact of envelope.facts ?? []) {
 83→    lines.push(`> *${fact.label}*: ${fact.value}`);
 84→  }
 85→
 86→  for (const action of envelope.actions ?? []) {
 87→    const target = action.target ? ` ${action.target}` : '';
 88→    const detail = action.detail ? ` - ${action.detail}` : '';
 89→    lines.push(`• ${action.verb}${target}: ${action.outcome}${detail}`);
 90→  }
 91→
 92→  if (envelope.options?.length) {
 93→    lines.push(`• Next: ${envelope.options.map((o) => o.label).join(' | ')}`);
 94→  }
 95→
 96→  if (envelope.ask?.trim()) {
 97→    lines.push(envelope.ask.trim());
 98→  }
 99→
100→  return lines.filter(Boolean).join('\n');
101→}
102→
103→function formatForSlack(text: string): string {
104→  let formatted = text.replace(/\r\n?/g, '\n');
105→
106→  // Convert markdown headers to Slack bold
107→  formatted = formatted
108→    .replace(/^### (.+)$/gm, '*$1*')
109→    .replace(/^## (.+)$/gm, '*$1*')
110→    .replace(/^# (.+)$/gm, '*$1*');
111→
112→  // Convert markdown bold to Slack bold
113→  formatted = formatted
114→    .replace(/\*\*([^*\n]+)\*\*/g, '*$1*')
115→    .replace(/__([^_\n]+)__/g, '*$1*');
116→
117→  // Clean up excessive whitespace
118→  formatted = formatted
119→    .replace(/\n{3,}/g, '\n\n')
120→    .replace(/[ \t]+$/gm, '');
121→
122→  // Slack has a 40,000 char limit per message
123→  if (formatted.length > 39000) {
124→    formatted = formatted.substring(0, 39000) + '\n\n_... message truncated_';
125→  }
126→
127→  return formatted;
128→}
129→
130→// =============================================================================
131→// TELEGRAM FORMATTING
132→// =============================================================================
133→
134→function composeTelegramResponse(envelope: ResponseEnvelope): string {
135→  const lines: string[] = [];
136→  const icon = envelope.emojiLevel === 'normal' ? severityEmojiUnicode(envelope.severity) : '';
137→
138→  if (envelope.title?.trim()) {
139→    lines.push(`${icon} <b>${escapeHtml(envelope.title.trim())}</b>`.trim());
140→  }
141→
142→  lines.push(`${icon} ${escapeHtml(envelope.summary)}`.trim());
143→
144→  for (const fact of envelope.facts ?? []) {
145→    lines.push(`- <b>${escapeHtml(fact.label)}</b>: ${escapeHtml(fact.value)}`);
146→  }
147→
148→  for (const action of envelope.actions ?? []) {
149→    const target = action.target ? ` ${escapeHtml(action.target)}` : '';
150→    const detail = action.detail ? ` - ${escapeHtml(action.detail)}` : '';
151→    lines.push(`- ${escapeHtml(action.verb)}${target}: ${escapeHtml(action.outcome)}${detail}`);
152→  }
153→
154→  if (envelope.options?.length) {
155→    lines.push(`- Next: ${envelope.options.map((o) => escapeHtml(o.label)).join(' | ')}`);
156→  }
157→
158→  if (envelope.ask?.trim()) {
159→    lines.push(escapeHtml(envelope.ask.trim()));
160→  }
161→
162→  return lines.filter(Boolean).join('\n');
163→}
164→
165→function severityEmojiUnicode(severity: ResponseEnvelope['severity']): string {
166→  switch (severity) {
167→    case 'success': return '\u2705';
168→    case 'warning': return '\u26a0\ufe0f';
169→    case 'error': return '\u274c';
170→    default: return '\ud83d\udcdd';
171→  }
172→}
173→
174→function escapeHtml(text: string): string {
175→  return text
176→    .replace(/&/g, '&amp;')
177→    .replace(/</g, '&lt;')
178→    .replace(/>/g, '&gt;');
179→}
180→
181→function formatForTelegram(text: string): string {
182→  let formatted = text.replace(/\r\n?/g, '\n');
183→
184→  // Convert markdown headers to bold HTML
185→  formatted = formatted
186→    .replace(/^### (.+)$/gm, '<b>$1</b>')
187→    .replace(/^## (.+)$/gm, '<b>$1</b>')
188→    .replace(/^# (.+)$/gm, '<b>$1</b>');
189→
190→  // Convert markdown bold/italic to HTML
191→  formatted = formatted
192→    .replace(/\*\*([^*\n]+)\*\*/g, '<b>$1</b>')
193→    .replace(/__([^_\n]+)__/g, '<b>$1</b>')
194→    .replace(/\*([^*\n]+)\*/g, '<i>$1</i>')
195→    .replace(/_([^_\n]+)_/g, '<i>$1</i>');
196→
197→  // Convert inline code
198→  formatted = formatted.replace(/`([^`\n]+)`/g, '<code>$1</code>');
199→
200→  // Clean up whitespace
201→  formatted = formatted
202→    .replace(/\n{3,}/g, '\n\n')
