208→  }
209→
210→  return formatted;
211→}
212→
213→// =============================================================================
214→// DISCORD FORMATTING
215→// =============================================================================
216→
217→function composeDiscordResponse(envelope: ResponseEnvelope): string {
218→  const lines: string[] = [];
219→  const icon = envelope.emojiLevel === 'normal' ? severityEmojiUnicode(envelope.severity) : '';
220→
221→  if (envelope.title?.trim()) {
222→    lines.push(`${icon} **${envelope.title.trim()}**`.trim());
223→  }
224→
225→  lines.push(`${icon} ${envelope.summary}`.trim());
226→
227→  for (const fact of envelope.facts ?? []) {
228→    lines.push(`> **${fact.label}**: ${fact.value}`);
229→  }
230→
231→  for (const action of envelope.actions ?? []) {
232→    const target = action.target ? ` ${action.target}` : '';
233→    const detail = action.detail ? ` - ${action.detail}` : '';
234→    lines.push(`- ${action.verb}${target}: ${action.outcome}${detail}`);
235→  }
236→
237→  if (envelope.options?.length) {
238→    lines.push(`- Next: ${envelope.options.map((o) => o.label).join(' | ')}`);
239→  }
240→
241→  if (envelope.ask?.trim()) {
242→    lines.push(envelope.ask.trim());
243→  }
244→
245→  return lines.filter(Boolean).join('\n');
246→}
247→
248→function formatForDiscord(text: string): string {
249→  let formatted = text.replace(/\r\n?/g, '\n');
250→
251→  // Discord supports full Markdown natively, minimal transformation needed
252→  // Just clean up whitespace
253→  formatted = formatted
