  1→/**
  2→ * @fileoverview Lightweight JavaScript sandbox for executing code snippets.
  3→ *
  4→ * Uses Node.js `vm` module to run untrusted JS in an isolated context with
  5→ * strict resource limits (timeout, memory ceiling via context restriction).
  6→ * This is the fallback when Docker-based execution is unavailable.
  7→ *
  8→ * Security model:
  9→ * - No access to `require`, `import`, `process`, `fs`, `child_process`
 10→ * - No access to global constructors that could escape the sandbox
 11→ * - Strict timeout enforcement
 12→ * - Output capture with size limits
 13→ *
 14→ * @module security/sandbox
 15→ */
 16→
 17→import vm from 'node:vm';
 18→import { logger } from '../utils/logger.js';
 19→
 20→// ============================================================================
 21→// Types
 22→// ============================================================================
 23→
 24→/** Configuration for sandbox execution. */
 25→export interface SandboxConfig {
 26→  /** Maximum execution time in milliseconds (default: 5000) */
 27→  timeoutMs: number;
 28→  /** Maximum output size in characters (default: 50000) */
 29→  maxOutputSize: number;
 30→  /** Additional safe globals to inject into the sandbox context */
 31→  globals: Record<string, unknown>;
 32→}
 33→
 34→/** Result of a sandbox execution. */
 35→export interface SandboxResult {
 36→  /** Whether execution completed without error */
 37→  success: boolean;
 38→  /** Captured console output */
 39→  output: string;
 40→  /** Return value of the last expression (serialized) */
 41→  returnValue: string | undefined;
 42→  /** Error message if execution failed */
 43→  error: string | undefined;
 44→  /** Execution duration in milliseconds */
 45→  durationMs: number;
 46→  /** Whether execution was terminated due to timeout */
 47→  timedOut: boolean;
 48→}
 49→
 50→// ============================================================================
 51→// Defaults
 52→// ============================================================================
 53→
 54→const DEFAULT_CONFIG: SandboxConfig = {
 55→  timeoutMs: 5_000,
 56→  maxOutputSize: 50_000,
 57→  globals: {},
 58→};
 59→
 60→// ============================================================================
 61→// Blocked patterns — reject code that attempts sandbox escape
 62→// ============================================================================
 63→
 64→const BLOCKED_PATTERNS = [
 65→  /\bprocess\b/,
 66→  /\brequire\s*\(/,
 67→  /\bimport\s*\(/,
 68→  /\bglobalThis\b/,
 69→  /\bFunction\s*\(/,
 70→  /\beval\s*\(/,
 71→  /\b__proto__\b/,
 72→  /\bconstructor\s*\[/,
 73→  /\bchild_process\b/,
 74→  /\bfs\b\.\b(read|write|unlink|mkdir|rmdir|rename|chmod|chown|stat|open|close)/,
 75→];
 76→
 77→// ============================================================================
 78→// Sandbox
 79→// ============================================================================
 80→
 81→/**
 82→ * Executes a JavaScript code snippet in an isolated VM context.
 83→ *
 84→ * The sandbox provides a minimal environment with:
 85→ * - `console.log/warn/error/info` (captured to output buffer)
 86→ * - `JSON`, `Math`, `Date`, `Array`, `Object`, `String`, `Number`,
 87→ *   `Boolean`, `RegExp`, `Map`, `Set`, `Promise`, `parseInt`, `parseFloat`,
 88→ *   `isNaN`, `isFinite`, `encodeURIComponent`, `decodeURIComponent`
 89→ * - `setTimeout` and `setInterval` (scoped, cleared on exit)
 90→ *
 91→ * Everything else (require, import, process, fs, etc.) is blocked.
 92→ */
 93→export function executeSandbox(
 94→  code: string,
 95→  config: Partial<SandboxConfig> = {},
 96→): SandboxResult {
 97→  const resolved: SandboxConfig = { ...DEFAULT_CONFIG, ...config };
 98→  const startTime = Date.now();
 99→
100→  // Pre-flight: reject obviously dangerous patterns before compilation
101→  for (const pattern of BLOCKED_PATTERNS) {
102→    if (pattern.test(code)) {
103→      return {
104→        success: false,
105→        output: '',
106→        returnValue: undefined,
107→        error: `Blocked: code contains restricted pattern ${pattern.source}`,
108→        durationMs: Date.now() - startTime,
109→        timedOut: false,
110→      };
111→    }
112→  }
113→
114→  // Build output capture buffer
115→  const outputLines: string[] = [];
116→  let outputSize = 0;
117→
118→  const appendOutput = (level: string, args: unknown[]): void => {
119→    const line = `[${level}] ${args.map(a => typeof a === 'object' ? JSON.stringify(a) : String(a)).join(' ')}`;
120→    if (outputSize + line.length <= resolved.maxOutputSize) {
121→      outputLines.push(line);
122→      outputSize += line.length;
123→    }
124→  };
125→
126→  // Scoped timer tracking for cleanup
127→  const timers: ReturnType<typeof setTimeout>[] = [];
128→  const intervals: ReturnType<typeof setInterval>[] = [];
129→
130→  // Build the sandbox context with safe globals only
131→  const sandboxGlobals: Record<string, unknown> = {
132→    // Console capture
133→    console: {
134→      log: (...args: unknown[]) => appendOutput('log', args),
135→      warn: (...args: unknown[]) => appendOutput('warn', args),
136→      error: (...args: unknown[]) => appendOutput('error', args),
137→      info: (...args: unknown[]) => appendOutput('info', args),
138→    },
139→
140→    // Safe built-in constructors and utilities
141→    JSON,
142→    Math,
143→    Date,
144→    Array,
145→    Object,
146→    String,
147→    Number,
148→    Boolean,
149→    RegExp,
150→    Map,
151→    Set,
152→    Promise,
153→    parseInt,
154→    parseFloat,
155→    isNaN,
156→    isFinite,
157→    encodeURIComponent,
158→    decodeURIComponent,
159→    encodeURI,
160→    decodeURI,
161→
162→    // Scoped timers (cleared on exit)
163→    setTimeout: (fn: (...args: unknown[]) => void, ms: number) => {
164→      const id = setTimeout(fn, Math.min(ms, resolved.timeoutMs));
165→      timers.push(id);
166→      return id;
167→    },
168→    setInterval: (fn: (...args: unknown[]) => void, ms: number) => {
169→      const id = setInterval(fn, Math.max(ms, 100)); // minimum 100ms interval
170→      intervals.push(id);
171→      return id;
172→    },
173→    clearTimeout,
174→    clearInterval,
175→
176→    // User-provided safe globals
177→    ...resolved.globals,
178→  };
179→
180→  const context = vm.createContext(sandboxGlobals, {
181→    name: 'fetch-sandbox',
182→    codeGeneration: {
183→      strings: false,  // Block eval() and new Function() from strings
184→      wasm: false,     // Block WebAssembly compilation
185→    },
186→  });
187→
188→  try {
189→    const script = new vm.Script(code, {
190→      filename: 'sandbox.js',
191→    });
192→
193→    const result = script.runInContext(context, {
194→      timeout: resolved.timeoutMs,
195→      breakOnSigint: true,
196→    });
197→
198→    // Serialize return value safely
199→    let returnValue: string | undefined;
200→    if (result !== undefined) {
201→      try {
202→        returnValue = typeof result === 'object'
203→          ? JSON.stringify(result, null, 2)
204→          : String(result);
205→      } catch {
206→        returnValue = '[unserializable]';
207→      }
208→    }
209→
210→    return {
211→      success: true,
212→      output: outputLines.join('\n'),
213→      returnValue,
214→      error: undefined,
215→      durationMs: Date.now() - startTime,
216→      timedOut: false,
217→    };
218→  } catch (error) {
219→    const errMsg = error instanceof Error ? error.message : String(error);
220→    const errCode = (error as NodeJS.ErrnoException)?.code ?? '';
221→    const isTimeout = errMsg.includes('timed out') ||
222→      errCode === 'ERR_SCRIPT_EXECUTION_TIMEOUT';
223→
224→    if (isTimeout) {
225→      logger.warn('Sandbox execution timed out', { timeoutMs: resolved.timeoutMs });
226→    } else {
227→      logger.debug('Sandbox execution error', { error });
228→    }
229→
230→    return {
231→      success: false,
232→      output: outputLines.join('\n'),
233→      returnValue: undefined,
234→      error: error instanceof Error ? error.message : String(error),
235→      durationMs: Date.now() - startTime,
236→      timedOut: isTimeout,
237→    };
238→  } finally {
239→    // Clean up any timers the sandboxed code created
240→    for (const id of timers) clearTimeout(id);
241→    for (const id of intervals) clearInterval(id);
242→  }
243→}
244→

